  /* base is AGCT/0..3 */
  for (i = 0; i < n; i++) {
     seq[i] = (base)((i+1)%4);
  }

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      table[i][j] = 0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
                                                   base POLYBENCH_1D(seq,N,n),
			                   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Create local restrict-qualified aliases to help the compiler
   * with alias analysis and enable better optimization. */
  base *restrict s = seq;
  DATA_TYPE (*restrict t)[n] = table;

#pragma scop
  /* Dynamic programming over increasing subsequence length.
   *
   * Original code iterated i from n-1 down to 0 and j from i+1 up to n-1.
   * The dependencies of Nussinov DP only go from shorter subsequences
   * to longer ones, so reordering the traversal to be by increasing
   * (j - i) preserves semantics:
   *
   *   - table[i][j-1]   has length (j-1 - i)   = (len-1)
   *   - table[i+1][j]   has length (j - i - 1) = (len-1)
   *   - table[i+1][j-1] has length (len-2)
   *   - table[i][k]     and table[k+1][j] both correspond to
   *     strictly smaller subintervals.
   *
   * Thus, for a given length 'len', all values needed by (i,j=i+len)
   * were computed at strictly smaller lengths.
   */
  for (int len = 1; len < n; ++len) {
    /* i ranges so that j = i + len stays < n */
    const int max_i = n - len;
    for (int i = 0; i < max_i; ++i) {
      const int j = i + len;

      /* Cache frequently-used row pointers in registers. */
      DATA_TYPE *restrict row_i   = t[i];
      DATA_TYPE *restrict row_ip1 = t[i+1];

      /* Base term: max of left (i,j-1) and below (i+1,j). */
      DATA_TYPE best = row_i[j-1];          /* table[i][j-1] */

      DATA_TYPE below = row_ip1[j];         /* table[i+1][j] */
      if (below > best)
        best = below;

      /* Diagonal / pairing term.
       *
       * Original:
       *   if (i < j-1)
       *     table[i][j] = max(table[i][j],
       *                        table[i+1][j-1] + match(seq[i], seq[j]));
       *   else
       *     table[i][j] = max(table[i][j], table[i+1][j-1]);
       *
       * Which is equivalent to:
       *   diag = table[i+1][j-1] +
       *          (i < j-1 ? match(seq[i], seq[j]) : 0);
       *   table[i][j] = max(table[i][j], diag);
       */
      DATA_TYPE diag = row_ip1[j-1];        /* table[i+1][j-1] */
      const int can_pair   = (i < j - 1);   /* don't allow adjacent elements to bond */
      const int pair_score = match(s[i], s[j]) & can_pair;
      diag += (DATA_TYPE)pair_score;
      if (diag > best)
        best = diag;

      /* Bifurcation term: split interval (i,j) at k.
       *
       * Original:
       *   for (k = i+1; k < j; k++)
       *     table[i][j] = max(table[i][j],
       *                        table[i][k] + table[k+1][j]);
       *
       * All table entries are non-negative:
       *   - table is initialized to 0;
       *   - updates are via max_score(.,.) and additions of match()∈{0,1};
       * therefore candidates table[i][k] + table[k+1][j] are ≥ 0.
       *
       * We can thus safely keep a separate maximum over k, initialized to 0,
       * and combine it with 'best' at the end:
       *   best <- max(best, max_k).
       *
       * This separation improves the compiler's ability to optimize
       * the inner loop.
       */
      DATA_TYPE max_k = 0;

      if (len > 1) {
        /* Number of k-iterations is (j - (i+1)) = len - 1 ≥ 1 here. */

        /* Pointer to table[k+1][j], for k = i+1 initially:
         * first k gives row index (i+1)+1 = i+2.
         */
        DATA_TYPE *restrict t_kp1j = &t[i+2][j];

        /* Pointer across row_i, starting at column k = i+1. */
        DATA_TYPE *restrict row_i_k     = row_i + (i + 1);
        DATA_TYPE *restrict row_i_k_end = row_i + j;

        /* Iterate k = i+1 .. j-1.
         *
         * At each step:
         *   row_i_k     -> table[i][k]
         *   t_kp1j      -> table[k+1][j]
         * with t_kp1j advanced by +n each iteration to move down the column.
         */
        while (row_i_k < row_i_k_end) {
          const DATA_TYPE candidate = *row_i_k + *t_kp1j;
          if (candidate > max_k)
            max_k = candidate;

          ++row_i_k;
          t_kp1j += n;  /* move to next row in column j */
        }
      }

      if (max_k > best)
        best = max_k;

      row_i[j] = best; /* table[i][j] */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
