  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

  /* Local aliases with 'restrict' to help the compiler optimize.
     These state that 'seq_' and 'table_' do not alias any other
     pointers that are used to access the same memory region. */
  const int n_local = n;
  base *restrict seq_ = seq;
  DATA_TYPE (*restrict table_)[n_local] = table;

#pragma scop
  /* Same iteration space as the original code:
     - Outer loop goes from bottom row to top (i = n-1 .. 0).
     - Inner loop sweeps j from left to right on each row (i+1 .. n-1).
     This preserves the original dependence order while giving good
     row-wise locality for table[i][j]. */
  for (i = n_local - 1; i >= 0; --i) {

    /* Cache frequently used row pointers once per 'i' to reduce
       address arithmetic inside the inner loops. Rows in a 2D
       row-major array are disjoint, so using separate restrict
       pointers for different rows is safe. */
    DATA_TYPE *restrict table_i = table_[i];
    DATA_TYPE *restrict table_ip1 = (i + 1 < n_local) ? table_[i + 1] : NULL;

    /* seq[i] is reused for all j in this row. */
    const base s_i = seq_[i];

    for (j = i + 1; j < n_local; ++j) {

      /* Keep the current cell value in a register and only write
         back once at the end. In the original version, table[i][j]
         was updated (load/compare/store) multiple times. */
      DATA_TYPE q = table_i[j];

      /* Dependency 1: from the left cell (i, j-1).
         In this loop nest, j always starts at i+1 >= 1,
         so j-1 is always >= 0; the original bound checks are
         therefore redundant and removed. */
      DATA_TYPE tmp = table_i[j - 1];
      if (tmp > q)
        q = tmp;

      /* Dependency 2: from the cell below (i+1, j).
         For all iterations that enter this loop, i <= n-2,
         hence i+1 < n_local and this access is always valid. */
      tmp = table_ip1[j];
      if (tmp > q)
        q = tmp;

      /* Dependency 3: from the diagonal (i+1, j-1),
         with the Nussinov base-pairing rule.

         In the original code this was guarded by:
           if (j-1 >= 0 && i+1 < _PB_N) { ... }
         which is always true for all (i,j) reached here.
         The only remaining condition is whether the two
         positions are adjacent (j == i+1) or not. */
      DATA_TYPE t_ip1_jm1 = table_ip1[j - 1];

      if (i < j - 1) {
        /* Non-adjacent positions: allow a bond. */
        DATA_TYPE pair_score = t_ip1_jm1 + match(s_i, seq_[j]);
        if (pair_score > q)
          q = pair_score;
      } else {
        /* Adjacent positions: no bond allowed; just propagate. */
        if (t_ip1_jm1 > q)
          q = t_ip1_jm1;
      }

      /* Dependency 4: bifurcation.  Try all possible splits k in (i,j)
         and keep the best. Each candidate is independent except for
         the running maximum 'q', so we keep that in a register. */
      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = table_i[k] + table_[k + 1][j];
        if (cand > q)
          q = cand;
      }

      /* Single store after all contributions have been considered. */
      table_i[j] = q;
    }
  }
#pragma endscop

}


