   including the call and return.
   Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
   with help from Allison Lake, Ting Zhou, and Tian Jin,
   based on algorithm by Nussinov, described in Allison Lake's senior thesis.

   Optimizations in this version:
   - Remove redundant boundary checks by tightening loop bounds.
   - Use local (restrict-qualified) pointers for seq/table to help the compiler
     with alias analysis and keep values in registers.
   - Accumulate the best score in a local variable and write table[i][j] once,
     instead of repeatedly updating it on every comparison.
   - Hoist frequently used row pointers (row_i, row_ip1) out of inner loops.
   - Partially unroll the inner k-loop to increase instruction-level parallelism.
   All transformations preserve the original dynamic-programming recurrence.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
                     base POLYBENCH_1D(seq,N,n),
                     DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

  /* Create local restrict-qualified views of the input arrays.
     This promises to the compiler that seq_local and table_local
     do not alias each other over their lifetimes in this function,
     which enables more aggressive optimization while preserving
     the original semantics for all valid calls. */
  base * __restrict__ seq_local = seq;
  DATA_TYPE (* __restrict__ table_local)[n] = table;

#pragma scop
  /* Outer loop over rows: we start at _PB_N-2 instead of _PB_N-1 because
     for i == _PB_N-1 the inner j-loop would be empty (j starts at i+1).
     This also guarantees i+1 < _PB_N inside the loop body, so we can drop
     corresponding bounds checks. */
  for (i = _PB_N - 2; i >= 0; i--) {

    base seq_i = seq_local[i];                 /* seq[i] reused across j-loop */
    DATA_TYPE * __restrict__ row_i   = table_local[i];
    DATA_TYPE * __restrict__ row_ip1 = table_local[i + 1]; /* i+1 < _PB_N by loop bound */

    /* j runs from i+1 upward; this ensures:
       - j-1 >= i >= 0  => no need to check j-1 >= 0
       - i+1 < _PB_N    => no need to check i+1 < _PB_N
       The access pattern row_i[j] remains contiguous (row-major). */
    for (j = i + 1; j < _PB_N; j++) {

      /* Start from the current cell value (initially zero from init_array).
         We will update 'best' with all competing options and store it back
         to table[i][j] once at the end. */
      DATA_TYPE best = row_i[j];

      /* Option 1: extend from the left, (i, j-1). */
      DATA_TYPE v = row_i[j - 1];
      if (v > best)
        best = v;

      /* Option 2: extend from below, (i+1, j). */
      v = row_ip1[j];
      if (v > best)
        best = v;

      /* Option 3: use diagonal (i+1, j-1) possibly plus a base pair (i, j).
         We must not allow adjacent bases to pair, i.e., only if i < j-1. */
      v = row_ip1[j - 1];
      if (i < j - 1) {
        int m = match(seq_i, seq_local[j]); /* 0 or 1 */
        DATA_TYPE pair_score = v + (DATA_TYPE)m;
        if (pair_score > best)
          best = pair_score;
      } else {
        /* Adjacent bases: only propagate the diagonal value as-is. */
        if (v > best)
          best = v;
      }

      /* Option 4: bifurcation over k: split interval (i, j) at k.
         Original loop: for (k = i+1; k < j; k++)
            best = max(best, table[i][k] + table[k+1][j]);
         We keep the same bounds but:
         - use row_i for table[i][k],
         - access table_local[k+1][j] directly,
         - accumulate into 'best' without repeatedly writing table[i][j],
         - partially unroll by a factor of 4 for better ILP. */

      /* Unrolled loop processes k, k+1, k+2, k+3 per iteration.
         Guard 'k + 3 < j' ensures that all used indices satisfy k' < j
         and k'+1 <= j, as in the original code. */
      for (k = i + 1; k + 3 < j; k += 4) {
        DATA_TYPE s0 = row_i[k]     + table_local[k + 1][j];
        if (s0 > best) best = s0;

        DATA_TYPE s1 = row_i[k + 1] + table_local[k + 2][j];
        if (s1 > best) best = s1;

        DATA_TYPE s2 = row_i[k + 2] + table_local[k + 3][j];
        if (s2 > best) best = s2;

        DATA_TYPE s3 = row_i[k + 3] + table_local[k + 4][j];
        if (s3 > best) best = s3;
      }

      /* Remainder loop for any remaining k values (0–3 iterations). */
      for ( ; k < j; k++) {
        DATA_TYPE s = row_i[k] + table_local[k + 1][j];
        if (s > best)
          best = s;
      }

      /* Commit the final best score for this cell. */
      row_i[j] = best;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

