                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.

  This version has been optimized for better data locality and reduced
  memory traffic while preserving the original semantics.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
               base POLYBENCH_1D(seq,N,n),
               DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  const int N = _PB_N;

  /* For very small instances there is nothing to do. This also avoids
     taking the address of table[0][0] when N could be 0. */
  if (N <= 1)
    return;

  /* Use restricted 1D views of the data to give the compiler clearer
     aliasing information and an explicit contiguous layout. */
  base      *restrict S = seq;
  DATA_TYPE *restrict T = &table[0][0];

#pragma scop
  /* Process the DP table row by row from bottom (i = N-2) to top (i = 0).
     For a fixed i, j increases, so we write table[i][j] in row-major order,
     which is cache friendly. */
  for (int i = N - 2; i >= 0; --i) {
    const int row_i   = i       * N;
    const int row_ip1 = (i + 1) * N;
    const base si = S[i];

    /* Handle j == i+1 separately: the two bases are adjacent and are
       not allowed to bond (no match term, and the split loop is empty). */
    {
      const int j = i + 1;
      const int idx_ij = row_i + j;

      DATA_TYPE q = T[idx_ij];

      const DATA_TYPE left = T[row_i   + (j - 1)]; /* table[i][j-1]   */
      const DATA_TYPE down = T[row_ip1 +  j     ]; /* table[i+1][j]   */
      const DATA_TYPE diag = T[row_ip1 + (j - 1)]; /* table[i+1][j-1] */

      if (left > q) q = left;
      if (down > q) q = down;
      /* Adjacent: i == j-1, so the original code does not add match(). */
      if (diag > q) q = diag;

      T[idx_ij] = q;
    }

    /* Remaining columns on this row: j >= i+2, where a base-pair between
       positions i and j is allowed. */
    for (int j = i + 2; j < N; ++j) {
      const int idx_ij = row_i + j;
      DATA_TYPE q = T[idx_ij];

      const DATA_TYPE left = T[row_i   + (j - 1)]; /* table[i][j-1]   */
      const DATA_TYPE down = T[row_ip1 +  j     ]; /* table[i+1][j]   */
      const DATA_TYPE diag = T[row_ip1 + (j - 1)]; /* table[i+1][j-1] */

      if (left > q) q = left;
      if (down > q) q = down;

      /* Here i < j-1 always holds, so the match term is always used,
         exactly as in the original guarded code. */
      const DATA_TYPE pair_val =
        diag + (DATA_TYPE)match(si, S[j]);

      if (pair_val > q) q = pair_val;

      /* Maximize over all splits k in (i, j):
           table[i][j] = max_k( table[i][k] + table[k+1][j] )
         Accesses:
           - T[row_i + k]       == table[i][k]
           - T[(k + 1)*N + j]   == table[k+1][j]
         The table is read-only in this loop body, so there are no
         loop-carried memory dependences through T. */
#if defined(__GNUC__)
#pragma GCC ivdep
#pragma GCC unroll 4
#endif
      for (int k = i + 1; k < j; ++k) {
        const DATA_TYPE candidate =
          T[row_i + k] + T[(k + 1) * N + j];
        if (candidate > q) q = candidate;
      }

      T[idx_ij] = q;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
